changeSet.sql:
alter procedure [graph].[GetLineageByAsset] --declare @assetUid uniqueidentifier, @startFromAssets varchar(2500) = null, @direction int = 3, @hops int = 5 as begin set nocount on;
if @hops > 25 begin set @hops = 25 end if @hops <= 0 begin set @hops = 3 end if @direction not between 1 and 3 begin set @direction = 3 end
drop table if exists #assetIds create table #assetIds (ID bigint, Class int) create index ix_TempAssetIds on #assetIds (ID asc)
drop table if exists #tbl drop table if exists #clean create table #tbl ([Hop] int, Uid uniqueidentifier, FromHop int, FromID bigint, subjectUid uniqueidentifier, FromPath nvarchar(2500), FromSegment xml, ToHop int, ToID bigint, objectUid uniqueidentifier, ToPath nvarchar(2500), ToSegment xml, predicateUid uniqueidentifier, [predicate] nvarchar(250), predicateType int) create table #clean ([Hop] int, ID bigint, [Path] nvarchar(2500), Segment xml) create index ix_TempTbl on #tbl ([Hop] desc, ToID asc)
declare @assetId bigint, @assetTypeClass int, @fakeLevel int = 1000000, @maxHops int = @hops*2
insert into #assetIds select distinct A.ID, T.[Class] from Asset A inner join AssetType T on T.ID = A.AssetTypeID and A.Uid = @assetUid
if not exists(select 1 from #assetIds) begin insert into #assetIds values(0, 0) end;
-- Get any descendant assets that may contain lineage data. with descendants as ( select S.ID as FromID, T.ID as ToID, T.AssetTypeID from graph.AssetNode S, graph.AssetEdge E, graph.AssetNode T, #assetIds A where MATCH(S-(E)->T) and E.PredicateType in (3, 4) and S.ID = A.ID union all select S.ID as FromID, T.ID as ToID, T.AssetTypeID from graph.AssetNode S, graph.AssetEdge E, graph.AssetNode T, descendants p where MATCH(S-(E)->T) and E.PredicateType in (3, 4) and S.ID = p.ToID ) insert into #assetIds select distinct D.ToID, T.Class from descendants D inner join AssetType T on T.ID = D.AssetTypeID;
-- Get any technical assets that are associated via the Business-To-Technical mapping predicate. insert into #assetIds select T.ID, TT.Class from graph.AssetNode S, graph.AssetEdge E, graph.AssetNode T, AssetType TT, #assetIds A where MATCH(S-(E)->T) and TT.ID = T.AssetTypeID and E.PredicateType = 13 -- Business To Technical predicate type and S.ID = A.ID and A.Class <> 8;
-- Backward-facing crawl - starting jump if @direction = 2 or @direction = 3 begin insert into #tbl ([Hop], Uid, FromHop, FromID, subjectUid, FromPath, FromSegment, ToHop, ToID, objectUid, ToPath, ToSegment, predicateUid, predicateType) select 0 as [Hop], E.Uid, -1 as FromHop, S.ID as FromID, S.Uid as FromUid, S.[Path] as FromPath, S.Segments as FromSegment, 0 as ToHop, T.ID as ToID, T.Uid as ToUid, T.[Path] as ToPath, T.Segments as ToSegment, --E.PredicateID, E.PredicateUid, E.PredicateType from graph.AssetNode S, graph.AssetEdge E, graph.AssetNode T, #assetIds A where MATCH(S-(E)->T) and E.PredicateType = 12 and T.ID = A.ID; end;
-- Forward-facing crawl - starting jump if @direction = 1 or @direction = 3 begin insert into #tbl ([Hop], Uid, FromHop, FromID, subjectUid, FromPath, FromSegment, ToHop, ToID, objectUid, ToPath, ToSegment, predicateUid, predicateType) select 0 as [Hop], E.Uid, 0 as FromHop, S.ID as FromID, S.Uid as FromUid, S.[Path] as FromPath, S.Segments as FromSegment, 1 as ToHop, T.ID as ToID, T.Uid as ToUid, T.[Path] as ToPath, T.Segments as ToSegment, --E.PredicateID, E.PredicateUid, E.PredicateType from graph.AssetNode S, graph.AssetEdge E, graph.AssetNode T, #assetIds A where MATCH(S-(E)->T) and E.PredicateType = 12 and S.ID = A.ID; end;
declare @current int = 1; while @current < @maxHops begin -- Backward-facing crawl if @direction = 2 or @direction = 3 begin insert into #tbl ([Hop], Uid, FromHop, FromID, subjectUid, FromPath, FromSegment, ToHop, ToID, objectUid, ToPath, ToSegment, predicateUid, predicateType) select -@current as [Hop], E.Uid, -@current-1 as FromHop, S.ID as FromID, S.Uid as FromUid, S.[Path] as FromPath, S.Segments as FromSegment, -@current as ToHop, T.ID as ToID, T.Uid as ToUid, T.[Path] as ToPath, T.Segments as ToSegment, --E.PredicateID, E.PredicateUid, E.PredicateType from graph.AssetNode S, graph.AssetEdge E, graph.AssetNode T, #tbl b where MATCH(S-(E)->T) and E.PredicateType = 12 and T.ID = b.FromID and b.[Hop] = -@current+1 and E.Uid not in (select Uid from #tbl) end;
-- Forward-facing crawl if @direction = 1 or @direction = 3 begin insert into #tbl ([Hop], Uid, FromHop, FromID, subjectUid, FromPath, FromSegment, ToHop, ToID, objectUid, ToPath, ToSegment, predicateUid, predicateType) select @current as [Hop], E.Uid, @current as FromHop, S.ID as FromID, S.Uid as FromUid, S.[Path] as FromPath, S.Segments as FromSegment, @current+1 as ToHop, T.ID as ToID, T.Uid as ToUid, T.[Path] as ToPath, T.Segments as ToSegment, --E.PredicateID, E.PredicateUid, E.PredicateType from graph.AssetNode S, graph.AssetEdge E, graph.AssetNode T, #tbl f where MATCH(S-(E)->T) and E.PredicateType = 12 and S.ID = f.ToID and f.[Hop] = @current-1 and E.Uid not in (select Uid from #tbl) end;
set @current = @current +1 end
update T set T.[predicate] = S.Name from #tbl T inner join [Predicate] S on S.Uid = T.predicateUid;
-- Now load any inferred links from the assetIDs table listed above. insert into #tbl ([Hop], Uid, FromHop, FromID, subjectUid, FromPath, FromSegment, ToHop, ToID, objectUid, ToPath, ToSegment, predicateUid, [predicate], predicateType) select C.[Hop], E.Uid, C.Hop as FromHop, S.ID as FromID, S.Uid as FromUid, S.[Path] as FromPath, S.Segments as FromSegment, C.Hop as ToHop, T.ID as ToID, T.Uid as ToUid, T.[Path] as ToPath, T.Segments as ToSegment, E.PredicateUid, P.Name as [Predicate], E.PredicateType from graph.AssetNode S, graph.AssetEdge E, graph.AssetNode T, #assetIds A, #tbl C, [Predicate] P where MATCH(S-(E)->T) and E.PredicateType = 13 and S.ID = A.ID and A.Class <> 8 and (C.FromID = T.ID or C.ToID = T.ID) and P.ID = E.PredicateID;
-- Get cleaned up version of unique nodes based on Hop and AssetUid. insert into #clean select FromHop, FromID, FromPath, FromSegment from #tbl
insert into #clean select N.ToHop, N.ToID, N.ToPath, N.ToSegment from #tbl N left join #clean E on E.Hop = N.ToHop and E.ID = N.ToID where E.ID is null
drop table if exists #hierarchies create table #hierarchies ([Hop] float, ID bigint, [Key] varchar(50), Back varchar(25), Fore varchar(25), HierarchyLevel int, AssetTypeID int, AssetID bigint, AssetUid uniqueidentifier, DisplayValue nvarchar(500), Class int, AssetTypeName nvarchar(250), Reveal bit, RelationCounts varchar(max), XmlPosition int, ParentKey varchar(50)) create index ix_TempHierarchies on #hierarchies ([Hop] asc, HierarchyLevel asc)
insert into #hierarchies select T.[Hop],
T.Segment.value('(/path/segment/@assetId)[1]', 'bigint'), --T.ID, utility.GetHash(cast(T.[Hop] as varchar) + '|' + doc.c.value('@assetId', 'varchar(50)')) as [Key], coalesce(S.[IconBackColor], '#000000'), coalesce(S.[IconForeColor], '#FFFFFF'), doc.c.value('@level', 'int') as [HierarchyLevel], doc.c.value('@assetTypeId', 'int') as [assetTypeId], doc.c.value('@assetId', 'bigint') as [assetId], A.Uid, d.DisplayValue, [AT].Class, [AT].Name as AssetTypeName, cast(0 as bit), '[]', doc.c.value('count(for $a in . return /path/segment[.<<$a])+1', 'int'), null from #clean T cross apply T.Segment.nodes('/path/segment') doc(c) inner join AssetDisplayValue d on d.AssetID = doc.c.value('@assetId', 'bigint') inner join AssetType [AT] on [AT].ID = doc.c.value('@assetTypeId', 'int') left join ObjectStyle S on S.ObjectType = [AT].Object and S.ObjectID = [AT].ObjectID inner join Asset A on A.ID = d.AssetID;
--Add Type as parent to those nodes that have a single-level hierarchy. drop table if exists #singles create table #singles (Hop int, ID bigint) insert into #singles select Hop, ID from #hierarchies group by Hop, ID having count(1) = 1;
update T set T.HierarchyLevel = 2, T.XmlPosition = 2 from #hierarchies T inner join #singles S on S.Hop = T.Hop and S.ID = T.ID;
insert into #hierarchies select T.Hop, T.ID, utility.GetHash(cast(T.[Hop] as varchar) + '|' + cast(A.Uid as varchar(50))), T.Back, T.Fore, 1 as HierarchyLevel, T.AssetTypeID, A.ID as AssetID, A.Uid as AssetUid, A.Name as DisplayValue, A.Class, A.Name as AssetTypeName, 0 as Reveal, '[]' as RelationCounts, 1 as XmlPosition, null as ParentKey from #hierarchies T inner join #singles S on S.Hop = T.Hop and S.ID = T.ID inner join AssetType A on A.ID = T.AssetTypeID;
update T set T.ID = T.AssetTypeID from #hierarchies T inner join #singles S on S.Hop = T.Hop and S.ID = T.ID;
-- Handle REVEAL logic. update T set T.Reveal = iif(S.[Count] > 0, 1, 0) from #hierarchies T inner join ( select J.AssetID, count(1) as [Count] from graph.AssetNode S, graph.AssetEdge E, graph.AssetNode T, ( select h.* from #hierarchies h inner join ( select max(Hop) as Hop, Max(HierarchyLevel) as HierarchyLevel from #hierarchies ) mh on mh.Hop = h.Hop and mh.HierarchyLevel = h.HierarchyLevel ) J where MATCH(S-(E)->T) and J.AssetID = S.ID group by J.AssetID ) S on S.AssetID = T.AssetID
-- Resolve the parent key. update C set C.ParentKey = P.[Key] from #hierarchies C left join #hierarchies P on P.Hop = C.Hop and P.ID = C.ID and P.XmlPosition = C.XmlPosition-1;
-- Now return the data sets to caller.
select * from #clean order by Hop;
select distinct * from #hierarchies order by Hop, ID, HierarchyLevel;
select [Hop], Uid, subjectUid, utility.GetHash(cast([FromHop] as varchar) + '|' + cast(FromID as varchar(50))) as [subjectKey], FromID as subjectId, objectUid, utility.GetHash(cast([ToHop] as varchar) + '|' + cast(ToID as varchar(50))) as [objectKey], ToID as objectId, predicateUid, [predicate], predicateType from #tbl order by Hop; end
